/*
 * A209252  Number of primes (excluding n) that may be generated by replacing
 *          any decimal digit of n with a digit from 0 to 9.
 * https://oeis.org/A209252
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = number of distinct primes obtained by replacing any
 *            decimal digit of n with a digit 0..9, excluding n itself.
 *            Implementation: brute‑force enumeration of all positions and
 *            replacement digits, testing primality and deduplicating results
 * Range:     u8 n <= 100, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   get_digits, is_prime_big, pow10
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>

#include "../utils/get_digits.h"
#include "../utils/pow10.h"
#include "../utils/is_prime_big.h"

seq_t a(idx_t n) {
    /* Convert n to its decimal digits (least‑significant first). */
    uint8_t buf[64];
    size_t len;
    get_digits((seq_t)n, buf, &len);

    /* Max number of different replacement results: len * 10. */
    seq_t primes[128];
    size_t prime_count = 0;

    /* Enumerate all positions and replacement digits. */
    for (size_t pos = 0; pos < len; ++pos) {
        uint8_t old = buf[pos];
        for (uint8_t d = 0; d <= 9; ++d) {
            if (d == old) continue;          /* would produce n itself */

            /* compute new number */
            seq_t powv = pow10(pos);           /* 10^pos */
            long long diff = (long long)d - (long long)old;
            unsigned long long m;
            if (diff >= 0) {
                m = (unsigned long long)n + (unsigned long long)diff * (unsigned long long)powv;
            } else {
                m = (unsigned long long)n - (unsigned long long)(-diff) * (unsigned long long)powv;
            }
            seq_t new_num = (seq_t)m;

            /* Keep only distinct primes. */
            if (is_prime_big(new_num)) {
                bool seen = false;
                for (size_t j = 0; j < prime_count; ++j) {
                    if (primes[j] == new_num) { seen = true; break; }
                }
                if (!seen) primes[prime_count++] = new_num;
            }
        }
    }
    return (seq_t)prime_count;
}
